export type CSVField = string;

/**
 * Parses a single CSV line into an array of field values.
 * Handles quoted fields (containing commas) and escaped quotes ("" -> ").
 */
export function parseCSVLine(line: string): string[] {
  const fields: string[] = [];
  let currentField = '';
  let inQuotes = false;
  let i = 0;

  while (i < line.length) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"') {
        // Check for escaped quote (double quote)
        if (i + 1 < line.length && line[i + 1] === '"') {
          currentField += '"';
          i += 2;
        } else {
          // End of quoted field
          inQuotes = false;
          i++;
        }
      } else {
        currentField += char;
        i++;
      }
    } else {
      if (char === '"') {
        // Start of quoted field
        inQuotes = true;
        i++;
      } else if (char === ',') {
        // Field separator
        fields.push(currentField);
        currentField = '';
        i++;
      } else {
        currentField += char;
        i++;
      }
    }
  }

  // Push the last field
  fields.push(currentField);

  return fields;
}

/**
 * Formats an array of fields into a single CSV line.
 * Wraps fields containing commas or quotes in double quotes,
 * and escapes internal quotes by doubling them.
 */
export function formatCSVLine(fields: string[]): string {
  return fields
    .map((field) => {
      // Check if the field needs quoting (contains comma, quote, or newline)
      if (field.includes(',') || field.includes('"') || field.includes('\n') || field.includes('\r')) {
        // Escape internal quotes by doubling them
        const escaped = field.replace(/"/g, '""');
        return `"${escaped}"`;
      }
      return field;
    })
    .join(',');
}
